create extension if not exists "uuid-ossp";
create table if not exists public.passkeys (id uuid primary key default uuid_generate_v4(), full_name text not null, email text not null, whatsapp text, tier text not null check (tier in ('silver','gold','platinum','diamond')), track text not null, lifecycle text default '30 days', key text unique not null, active boolean default true, fingerprint text, payment_ref text, amount numeric, currency text check (currency in ('NGN','USD')), created_at timestamp with time zone default now());
create table if not exists public.payments (id uuid primary key default uuid_generate_v4(), reference text unique not null, email text not null, amount numeric not null, currency text not null, tier text not null, track text, status text default 'pending' check (status in ('pending','success','failed')), gateway text default 'paystack' check (gateway in ('paystack','stripe')), gateway_response jsonb, passkey_id uuid references public.passkeys(id), created_at timestamp with time zone default now());
create table if not exists public.feed_items (id uuid primary key default uuid_generate_v4(), author text not null, track text, tier text, code text, text_content text, media_url text, media_type text check (media_type in ('image','video','voice','file','code', null)), media_bucket text, created_at timestamp with time zone default now());
create table if not exists public.teacher_assets (id uuid primary key default uuid_generate_v4(), teacher_email text not null, title text, code text, media_url text, media_type text, is_pushed boolean default false, created_at timestamp with time zone default now());
create table if not exists public.leads (id uuid primary key default uuid_generate_v4(), company_name text not null, service text not null, brief text, budget text, contact text, delegated_to text, status text default 'new' check (status in ('new','contacted','delegated','closed')), created_at timestamp with time zone default now());
create table if not exists public.tasks (id uuid primary key default uuid_generate_v4(), title text not null, spec text, track text, video_url text, created_by text, created_at timestamp with time zone default now());
create table if not exists public.submissions (id uuid primary key default uuid_generate_v4(), task_id uuid references public.tasks(id) on delete cascade, student_email text not null, student_name text, proof_url text not null, proof_type text check (proof_type in ('video','image','audio','file')), log text, status text default 'pending' check (status in ('pending','approved','rejected')), created_at timestamp with time zone default now());
create table if not exists public.audit_log (id uuid primary key default uuid_generate_v4(), actor text, action text not null, meta jsonb, created_at timestamp with time zone default now());
create table if not exists public.pricing_config (id int primary key check (id = 1), silver_ngn int default 45000, gold_ngn int default 85000, platinum_ngn int default 150000, diamond_ngn int default 300000, silver_usd int default 45, gold_usd int default 85, platinum_usd int default 150, diamond_usd int default 300, naira_brackets jsonb default '["₦300,000 - ₦800,000","₦800,000 - ₦1,500,000","₦1,500,000 - ₦5,000,000","₦5,000,000+"]'::jsonb, usd_brackets jsonb default '["$500 - $1,500","$1,500 - $3,000","$3,000 - $10,000","$10,000+"]'::jsonb, updated_at timestamp with time zone default now());
insert into public.pricing_config (id) values (1) on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('videos', 'videos', true) on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('images', 'images', true) on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('voice-notes', 'voice-notes', true) on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('feed-assets', 'feed-assets', true) on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('submissions', 'submissions', true) on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('teacher-private', 'teacher-private', false) on conflict (id) do nothing;
alter table public.passkeys enable row level security; alter table public.payments enable row level security; alter table public.feed_items enable row level security; alter table public.teacher_assets enable row level security; alter table public.leads enable row level security; alter table public.tasks enable row level security; alter table public.submissions enable row level security; alter table public.audit_log enable row level security; alter table public.pricing_config enable row level security;
create policy "Allow all for anon" on public.passkeys for all using (true) with check (true); create policy "Allow all for anon" on public.payments for all using (true) with check (true); create policy "Allow all for anon" on public.feed_items for all using (true) with check (true); create policy "Allow all for anon" on public.teacher_assets for all using (true) with check (true); create policy "Allow all for anon" on public.leads for all using (true) with check (true); create policy "Allow all for anon" on public.tasks for all using (true) with check (true); create policy "Allow all for anon" on public.submissions for all using (true) with check (true); create policy "Allow all for anon" on public.audit_log for all using (true) with check (true); create policy "Allow all for anon" on public.pricing_config for all using (true) with check (true);
create policy "Public read videos" on storage.objects for select using (bucket_id = 'videos'); create policy "Allow upload videos" on storage.objects for insert with check (bucket_id = 'videos'); create policy "Public read images" on storage.objects for select using (bucket_id = 'images'); create policy "Allow upload images" on storage.objects for insert with check (bucket_id = 'images'); create policy "Public read voice" on storage.objects for select using (bucket_id = 'voice-notes'); create policy "Allow upload voice" on storage.objects for insert with check (bucket_id = 'voice-notes'); create policy "Public read feed" on storage.objects for select using (bucket_id = 'feed-assets'); create policy "Allow upload feed" on storage.objects for insert with check (bucket_id = 'feed-assets'); create policy "Public read submissions" on storage.objects for select using (bucket_id = 'submissions'); create policy "Allow upload submissions" on storage.objects for insert with check (bucket_id = 'submissions');